def table(label,caption,headers,rows):
    esc=lambda s:str(s).replace('_',r'\_')
    return '\n'.join([r'\begin{table}[!htbp]\centering\scriptsize',r'\caption{'+caption+r'}\label{'+label+'}',r'\begin{tabular}{'+'l'*len(headers)+r'}\toprule',' & '.join(headers)+r'\\\midrule',*[' & '.join(esc(x) for x in row)+r'\\' for row in rows],r'\bottomrule\end{tabular}\end{table}'])
def replace_table(src,label,replacement):
    pattern=r'\\begin\{table\}.*?\\end\{table\}'
    matches=[m for m in re.finditer(pattern,src,re.S) if r'\label{'+label+'}' in m.group()]
    assert len(matches)==1,label
    m=matches[0];return src[:m.start()]+replacement+src[m.end():]
def spacing(src):
    # Protect equations, citation/label keys, asset paths, code identifiers and proper names.
    protected=r'\\begin\{(?:equation|align)\*?\}.*?\\end\{(?:equation|align)\*?\}|\$[^$]*\$|\\(?:cite\w*|ref|label|includegraphics|texttt)\s*(?:\[[^\]]*\])?\{[^}]*\}|IC3Net|G2ANet|V2X|SHA256|\b2k\b|\bThreadripper3960X\b|\b2\.11\.0\+cu128\b'
    def prose(s):
        s=re.sub(r'(?<=[a-zA-Z])(?=\d)', ' ',s)
        s=re.sub(r'(?<=\d)(?=[a-zA-Z])', ' ',s)
        s=re.sub(r'(?<=[A-Za-z]),(?=\S)', ', ',s)
        return s
    head,body=src.split(r'\begin{document}',1);parts=re.split('('+protected+')',body,flags=re.S)
    return head+r'\begin{document}'+''.join(p if i%2 else prose(p) for i,p in enumerate(parts))
