    src=src.replace(r'\includegraphics[width=\linewidth]{figure3_medium.pdf}',r'\includegraphics[width=\linewidth,height=0.68\textheight,keepaspectratio]{figure3_medium.pdf}').replace(r'\begin{figure}[tbp]',r'\begin{figure}[!htbp]')
    for old,new in [('slow'+r'\_'+'5ms','Slow/5 ms'),('medium'+r'\_'+'2ms','Medium/2 ms'),('medium'+r'\_'+'5ms','Medium/5 ms')]:src=src.replace(old,new)
    cohort=r'Primary Hallway & Fresh, 1500 updates & 10 seeds; Oracle/BC & Matched-condition independently learned policies; Table~\ref{tab:primary}.\\'
    src=src.replace(cohort,cohort+'\n'+r'Primary frozen diagnostics & Same primary weights & 10 seeds; no retraining & Fresh subsets, common prefix and readiness controls; Tables~\ref{tab:new_fresh}--\ref{tab:new_prefix}.\\'+'\n'+r'Broadcast decomposition & Same hidden-task weights & 10 seeds; 20 resets & Fixed readiness; differs from the 50-reset measured learning check; Tables~\ref{tab:broadcast_decomp},\ref{tab:hidden}.\\')
    from .robustness.manuscript import integrate
    src=integrate(src)
    before,after=src.split(r'\appendix',1);after=re.sub(r'(?<!\\clearpage\n)\\section\{',lambda _:r'\clearpage'+'\n'+r'\section{',after)
    src=before+r'\appendix'+after
    return spacing(src)
